import re

def parse_price(s: str) -> float:
    # Remove dollar sign and commas
    cleaned = re.sub(r'[,$]', '', s)
    # Split into whole and fractional parts
    if '.' in cleaned:
        whole, fractional = cleaned.split('.')
    else:
        whole, fractional = cleaned, ''
    # Pad fractional part with zeros if needed
    fractional = fractional.ljust(2, '0')[:2]
    # Convert to float
    return float(f"{whole}.{fractional}")

